+const { useState } = React;
+
+const FAQ_DATA = [
+    {
+        question: "Why do cats purr?",
+        answer: "Cats often purr when they are happy or relaxed, but they also purr to soothe themselves when they are stressed, in pain, or even dying. It's a versatile communication tool and a self-healing mechanism."
+    },
+    {
+        question: "Why do cats have whiskers?",
+        answer: "Whiskers are highly sensitive tactile organs. They help cats navigate in the dark, detect changes in air currents, and determine if they can fit through tight spaces."
+    },
+    {
+        question: "How long do cats sleep?",
+        answer: "On average, cats sleep for 12 to 16 hours a day. They are crepuscular, meaning they are most active during dawn and dusk, which is why they seem to sleep all day."
+    },
+    {
+        question: "Why do cats bring you 'gifts'?",
+        answer: "In the wild, mother cats teach their young how to eat by bringing them dead or injured prey. When a pet cat does this, they are often treating you like their 'family' and trying to teach you how to hunt."
+    },
+    {
+        question: "Why do cats like boxes?",
+        answer: "Boxes provide a sense of security and safety. In a confined space, cats feel they can't be snuck up on from behind or the side, and it also helps them conserve body heat."
+    }
+];
+
+function FAQItem({ question, answer }) {
+    const [isOpen, setIsOpen] = useState(false);
+
+    return (
+        <div className="example">
+            <button 
+                className="question-button" 
+                onClick={() => setIsOpen(!isOpen)}
+                aria-expanded={isOpen}
+            >
+                <span>{question}</span>
+                <span className={`arrow ${isOpen ? 'open' : ''}`}>▼</span>
+            </button>
+            <div className={`details ${isOpen ? 'open' : ''}`}>
+                {answer}
+            </div>
+        </div>
+    );
+}
+
+function App() {
+    return (
+        <div>
+            <h1>Cat FAQ</h1>
+            {FAQ_DATA.map((item, index) => (
+                <FAQItem key={index} question={item.question} answer={item.answer} />
+            ))}
+        </div>
+    );
+}
+
+const root = ReactDOM.createRoot(document.getElementById('root'));
+root.render(<App />);
+
')

